@derive(Clone)
class Node:
    children: Array[Node] = []
    parent: weakref Node = None
    tag: int = 0
    fn add(owns c: Node):
        c.parent = weakref this
        this.children.push(owns c)       # the one `x.parent = weakref o` line in the package: condition 1 holds

fn main():
    root = Node()
    root.add(owns Node())
    twin = copy of root.children[0]      # [OWN-8]: the `weakref` field is copied as "one more link to the same target"; `twin` is nobody's child
    mem.drop(owns root)                  # root ends; its block stays (twin's link holds a weak count)
    if twin.parent exists as p:          # <- compiled as "a plain load and a test for no link" (condition 1 proved, condition 2 holds: nothing here ends a Node after `twin` is known to live)
        println(p.children.len())        # reads an ended object: its `children` buffer is freed

class Node:
    children: Array[Node] = []
    parent: weakref Node = None
    name: String
    fn add(owns c: Node):
        c.parent = weakref this
        this.children.push(owns c)

class Leaf(Node):
    fn drop():
        if this.parent exists as p:      # <- condition 1 read for `Node` ("their class has no drop of its own" read as the declared class); condition 2: no line in `drop` ends a Node: compiled with no header test
            println(p.name)              # the parent is being ended: [DRP-2] drops its fields in reverse order, `name` before `children`, so `p.name`'s text is freed when the Leaf's drop runs

fn main():
    root = Node(name=String("root"))
    root.add(owns Leaf(name=String("leaf")))
    # root ends here: Node has no drop; `name` freed, then `parent`, then `children`, whose Leaf's drop reads `p.name`

class Player:
    name: String

fn main():
    w: weakref Player = None
    if true:
        p = Player(name=String("a"))   # one owner: "not counted": is the header's count written 1 here?
        w = weakref p                   # 12-byte header; weak count 2
    # `p` ended: is its count written 0 before its drop, as [RT-10] says only of "the subtract that reaches zero"?
    if w exists as q:                   # <- [WK-12]: "tests the target's header (does the object still live?)": which number? An implementer who writes neither 1 nor 0 reads what the allocator left
        println(q.name)                 # a freed String if the count still reads 1

class Big:
    n: int = 0
class Holder:
    b: thread_shared Big

fn main():
    a = thread_shared Holder(b=thread_shared Big())   # no owner, link or view of `a` or of its Big outlives `main`: [OPT-1] MAY put both in main's frame "with the same header"
    with tasks = scope():
        tasks.run(fn() thread_shared a:               # `a` handed over at the capture; its Big travels inside it ([RC-4] point 5)
            c = thread_shared a.b                     # <- a count operation on another thread: home or away? "Which thread made a value is read from the header of the memory chunk its block came from": the block is in a stack frame (or a manager's memory), and the chunk header read is whatever lies at that address: a plain add on a count the maker also adds to, a data race on the count
            c.n)

fn a(ref mut dst: MutSpan[float], other: Array[float]):
    dst = ref mut other.as_mut_span()     # [BRW-14]: "points the caller's `d` at it"
fn b(ref mut c: Counter, other: ref mut Counter):
    c = ref mut other                     # [BRW-14]: "points `c`, for the rest of the call, at that place": the caller's variable is unchanged
# an implementer must find the rule that separates the two lines

class Player:
    name: String
    fn register():
        REGISTRY.push(shares this)       # outside drop: [OBJ-5] refuses it only inside `drop`; [RC-1] lists "a plain parameter" as E2122 and does not name `this`; a one-owner object's count is not maintained, so an owner made here is honoured by nothing

fn keep(p: shares Player):
    LIST.push(shares p)                  # `p` is a view of the caller's owner, of a shared type: "a name that is already such an owner"?
